"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[73055],{73055:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/5dd7436cb6f5b6564cc198f61cb95bbe.jpg\\"\\n  title=\\"Patricia Coffee Brewers\\"\\n  cuisine=\\"Cafe\\"\\n  address=\\"Rear of, 493-495 Little Bourke St, Melbourne VIC 3000 Australia\\"\\n  rating=3.5\\n  tags=\\"cafe\\"\\n/>\\n</center>\\n\\n## Review\\nVisited because it\'s renowned as one of Melbourne\'s <mark>top 3 coffees</mark>.  \\nAs expected, there was quite a queue given its popularity.\\n\\nI thought the crowd would mean a long wait, but the line moved faster than expected and I was able to order in no time.\\n\\nWhen I ordered a <mark>Long Black</mark> and asked for a medium size, the staff kindly let me know that\'s called a `Long Long Black`.  \\nThey ask for your name when you order, then call it out when your coffee is ready outside.  \\nWhile waiting, they also handed out a glass of water each.\\n\\n```adcard\\n```\\n\\nBeing a weekday, most people seemed to be office workers grabbing takeout on their way to work.\\n\\nI\'m not sure it was noticeably better than other places, but as always, Australian coffee delivered wherever I went.  \\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/5dd7436cb6f5b6564cc198f61cb95bbe.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Patricia Coffee Brewers\\">\\n</pictures>\\n"}')}}]);